// Web worker running the TypeSpec compiler (bundled by scripts/build-tsp.mjs).

import { compileProject } from './compile.ts';
import type { CompileRequest, CompileResponse } from './protocol.ts';
// generated by scripts/build-tsp.mjs: library .tsp files and JS modules
import { libraries } from './tsp-libs.generated.js';

const ctx = self as unknown as { onmessage: ((ev: MessageEvent<CompileRequest>) => void) | null; postMessage(msg: CompileResponse): void };

let queue: Promise<void> = Promise.resolve();

ctx.onmessage = (ev) => {
  const req = ev.data;
  // one compilation at a time
  queue = queue.then(async () => {
    try {
      const result = await compileProject(req, libraries);
      ctx.postMessage({ id: req.id, ok: true, ...result });
    } catch (err) {
      ctx.postMessage({ id: req.id, ok: false, error: err instanceof Error ? (err.stack ?? err.message) : String(err) });
    }
  });
};
